var base64=(function(){var _PADCHAR="=",_ALPHA="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/",_VERSION="1.0";function _getbyte64(s,i){var idx=_ALPHA.indexOf(s.charAt(i));if(idx===-1){throw"Cannot decode base64"}return idx}function _decode(s){var pads=0,i,b10,imax=s.length,x=[];s=String(s);if(imax===0){return s}if(imax%4!==0){throw"Cannot decode base64"}if(s.charAt(imax-1)===_PADCHAR){pads=1;if(s.charAt(imax-2)===_PADCHAR){pads=2}imax-=4}for(i=0;i<imax;i+=4){b10=(_getbyte64(s,i)<<18)|(_getbyte64(s,i+1)<<12)|(_getbyte64(s,i+2)<<6)|_getbyte64(s,i+3);x.push(String.fromCharCode(b10>>16,(b10>>8)&255,b10&255))}switch(pads){case 1:b10=(_getbyte64(s,i)<<18)|(_getbyte64(s,i+1)<<12)|(_getbyte64(s,i+2)<<6);x.push(String.fromCharCode(b10>>16,(b10>>8)&255));break;case 2:b10=(_getbyte64(s,i)<<18)|(_getbyte64(s,i+1)<<12);x.push(String.fromCharCode(b10>>16));break}return x.join("")}function _getbyte(s,i){var x=s.charCodeAt(i);if(x>255){throw"INVALID_CHARACTER_ERR: DOM Exception 5"}return x}function _encode(s){if(arguments.length!==1){throw"SyntaxError: exactly one argument required"}s=String(s);var i,b10,x=[],imax=s.length-s.length%3;if(s.length===0){return s}for(i=0;i<imax;i+=3){b10=(_getbyte(s,i)<<16)|(_getbyte(s,i+1)<<8)|_getbyte(s,i+2);x.push(_ALPHA.charAt(b10>>18));x.push(_ALPHA.charAt((b10>>12)&63));x.push(_ALPHA.charAt((b10>>6)&63));x.push(_ALPHA.charAt(b10&63))}switch(s.length-imax){case 1:b10=_getbyte(s,i)<<16;x.push(_ALPHA.charAt(b10>>18)+_ALPHA.charAt((b10>>12)&63)+_PADCHAR+_PADCHAR);break;case 2:b10=(_getbyte(s,i)<<16)|(_getbyte(s,i+1)<<8);x.push(_ALPHA.charAt(b10>>18)+_ALPHA.charAt((b10>>12)&63)+_ALPHA.charAt((b10>>6)&63)+_PADCHAR);break}return x.join("")}return{decode:_decode,encode:_encode,VERSION:_VERSION}}());
var decrypt=(function(s){var n=s.content;var r=s.keys;var t=s.keys.length;var q=s.accessKey;var o=q.split("");var m=o.length;var k=new Array();k.push(r[(o[m-1].charCodeAt(0))%t]);k.push(r[(o[0].charCodeAt(0))%t]);for(i=0;i<k.length;i++){n=base64.decode(n);var p=k[i];var j=base64.encode(n.substr(0,16));var f=base64.encode(n.substr(16));var h=CryptoJS.format.OpenSSL.parse(f);n=CryptoJS.AES.decrypt(h,CryptoJS.enc.Base64.parse(p),{iv:CryptoJS.enc.Base64.parse(j),format:CryptoJS.format.OpenSSL});if(i<k.length-1){n=n.toString(CryptoJS.enc.Base64);n=base64.decode(n)}}return n.toString(CryptoJS.enc.Utf8)});
var ajax=(function(p,b,h){var r=java.post("https://wap.ciweimao.com/chapter/"+p,b,h).body();try{return JSON.parse(r)}catch(e){java.log(e)}});

if(!String(cookie.getCookie(source.key))){
cookie.setCookie(source.key,java.head(source.key,source.getHeaderMap(false)).cookies().entrySet().toArray().join("; "));
}
var body = "chapter_id="+baseUrl.match(/\d+/)[0];
var header = {"User-Agent":java.webViewUA,"Referer":baseUrl,"Cookie":cookie.getCookie(source.key),"Accept-Encoding":"gzip, deflate"};
if(/id="J_BookRead_WaterMark"/.test(result)){
var access_key = ajax("ajax_get_session_code",body,header).chapter_access_key;
var res = ajax("get_book_chapter_detail_info",body+"&chapter_access_key="+access_key,header);
decrypt({"content":res.chapter_content,"keys":res.encryt_keys,"accessKey":access_key}).replace(/<span>\w+<\/span>/g,"");
}
if(/id="J_BookImage"/.test(result)){
var res = ajax("ajax_get_image_session_code",body,header);
var code = decrypt({"content":res.image_code,"keys":res.encryt_keys,"accessKey":res.access_key});
var path = body+"&area_width=680&font_size=33&image_code="+code+"&bg_color_name=white&text_color_name=white";
var height = java.post("https://wap.ciweimao.com/chapter/get_book_chapter_image_height?"+path,"",header).body();
var count = Math.ceil(parseInt(height)/1280);
var imgList = ["<img src=\"https://wap.ciweimao.com/chapter/book_chapter_image?"+path+",{\"headers\":{\"Referer\":\""+baseUrl+"\"}}\">"];
var mid = java.md5Encode16(path);
var pid = 1;
while(pid<count){
imgList.push("<img src=\"https://pss.bdstatic.com/more/img/map.jpg?#"+mid+"#"+(pid++)+"\">");
}
imgList.join("\n");
}

ruleContent.imageDecode:
var [_, mid, pid] = src.split("#");
if (src.includes("chapter_image")) {
  var bmp = Packages.android.graphics.BitmapFactory.decodeByteArray(result,0,result.length);
  var path = src.split("?")[1].split(",")[0];
  mid = java.md5Encode16(path);
  cache.putMemory(mid, bmp);
  pid = "0";
}
if (mid && pid) {
  var ByteArrayOutputStream = Packages.java.io.ByteArrayOutputStream;
  var Bitmap = Packages.android.graphics.Bitmap;
  var bmp = cache.getFromMemory(mid);
  var width = bmp.getWidth();
  var height = bmp.getHeight();
  var count = Math.ceil(height / 1280);
  var page = parseInt(pid);
  var newHeight = 1280;
  if (height%1280 > 0 && page+2 > count) {
    newHeight = parseInt(height % 1280);
  }
  var newBmp = Bitmap.createBitmap(bmp, 0, page * 1280, width, newHeight, null, true);
  var byteStream = new ByteArrayOutputStream();
  newBmp.compress(Bitmap.CompressFormat.JPEG, 100, byteStream);
  result = byteStream.toByteArray();
  byteStream.close();
}
result

